-- Development/demo seed. Idempotent and separate from production migrations.
select 'NV'||lpad(i::text,3,'0'),(array['Nguyễn Văn An','Trần Thị Bình','Lê Minh Cường','Phạm Thu Dung','Hoàng Quốc Dũng','Vũ Ngọc Hà','Đỗ Thành Hưng','Bùi Mai Lan','Ngô Hải Long','Đặng Thu Mai','Trịnh Văn Nam','Đinh Hồng Nhung','Lý Hoàng Phúc','Mai Kim Quý','Tạ Thanh Sơn'])[i],('10000000-0000-0000-0000-00000000000'||(((i-1)%3)+1))::uuid,case when i<=3 then 'Trưởng nhóm' else 'Nhân viên' end,'nv'||lpad(i::text,3,'0')||'@tlp.demo' from generate_series(1,15) i on conflict(employee_code) do nothing;
select '40000000-0000-0000-0000-000000000001','AT'||lpad(i::text,3,'0'),'Tình huống an toàn lao động số '||i||': hành động nào phù hợp nhất?','Tuân thủ hướng dẫn và báo cáo người phụ trách giúp giảm thiểu rủi ro.',1 from generate_series(1,20)i on conflict(bank_id,question_code) do nothing;
select q.id,o.code,o.label,o.code=chr(65+((substring(q.question_code from 3)::int-1)%4)),o.ord from questions q cross join(values('A','Kiểm tra và thực hiện đúng hướng dẫn',1),('B','Bỏ qua vì chưa có sự cố',2),('C','Tự xử lý khi chưa được đào tạo',3),('D','Tiếp tục làm việc và báo sau',4))o(code,label,ord) where q.bank_id='40000000-0000-0000-0000-000000000001' on conflict(question_id,option_code) do nothing;
